  "onboarding.l1_intro_subtitle": "Here's what to expect based on your language background.",
  "onboarding.l1_intro_romance_title": "You have an advantage!",
  "onboarding.l1_intro_romance_advantage": "Close languages",
  "onboarding.l1_intro_romance_advantage_text": "Your language shares many words and structures with Portuguese. You'll progress faster than most learners.",
  "onboarding.l1_intro_romance_traps": "Watch out for false friends",
  "onboarding.l1_intro_romance_traps_text": "Some words look the same but mean different things. We'll highlight these throughout your journey so you avoid common mistakes.",
  "onboarding.l1_intro_romance_sounds": "New sounds to learn",
  "onboarding.l1_intro_romance_sounds_text": "European Portuguese has nasal vowels, reduced vowels, and unique sounds like 'lh' and 'nh' that don't exist in your language. We'll train your ear.",
  "onboarding.l1_intro_cjk_title": "A new writing system",
  "onboarding.l1_intro_cjk_alphabet": "The Latin alphabet",
  "onboarding.l1_intro_cjk_alphabet_text": "Portuguese uses the Latin alphabet (A-Z) with special characters like ç, ã, õ, é, ê. We'll introduce each letter with its Portuguese sound.",
  "onboarding.l1_intro_cjk_sounds": "Very different sounds",
  "onboarding.l1_intro_cjk_sounds_text": "Portuguese has sounds that don't exist in your language: nasal vowels, rolling 'r', and consonant clusters. Each lesson includes pronunciation practice with visual guides.",
  "onboarding.l1_intro_cjk_grammar": "Grammar is different",
  "onboarding.l1_intro_cjk_grammar_text": "Portuguese has gendered nouns (masculine/feminine), verb conjugations that change with each person, and articles before nouns. We'll build these up step by step.",
  "onboarding.l1_intro_rtl_title": "From right-to-left to left-to-right",
  "onboarding.l1_intro_rtl_direction": "Reading direction",
  "onboarding.l1_intro_rtl_direction_text": "Portuguese reads left-to-right. We'll help you get comfortable with this through exercises designed for your visual habits.",
  "onboarding.l1_intro_rtl_vowels": "Written vowels everywhere",
  "onboarding.l1_intro_rtl_vowels_text": "Unlike your language, Portuguese writes all vowels explicitly. You'll see a, e, i, o, u in every word. Portuguese also has nasal vowels (ã, õ) with their own sounds.",
  "onboarding.l1_intro_rtl_gender": "Grammatical gender",
  "onboarding.l1_intro_rtl_gender_text": "Portuguese has masculine and feminine nouns, but the rules differ from your language. We'll highlight the differences to avoid confusion.",
  "onboarding.l1_intro_general_title": "What to expect",
  "onboarding.l1_intro_general_sounds": "Unique sounds",
  "onboarding.l1_intro_general_sounds_text": "European Portuguese has nasal vowels, reduced sounds, and a distinctive rhythm. Each lesson includes pronunciation guides tailored to speakers of your language.",
  "onboarding.l1_intro_general_grammar": "Grammar essentials",
  "onboarding.l1_intro_general_grammar_text": "Portuguese has gendered nouns, verb conjugations, and articles. We'll introduce each concept gradually with comparisons to your language where helpful.",
  "onboarding.l1_intro_indic_title": "A new writing system",
  "onboarding.l1_intro_indic_alphabet": "The Latin alphabet",
  "onboarding.l1_intro_indic_alphabet_text": "Portuguese uses the Latin alphabet (A-Z) instead of Devanagari or Bengali script. We'll introduce each letter with its Portuguese sound, including special characters like ç, ã, õ, é, ê.",
  "onboarding.l1_intro_indic_sounds": "Familiar and new sounds",
  "onboarding.l1_intro_indic_sounds_text": "Some Portuguese sounds are similar to yours — like the retroflex 'r'. But nasal vowels, reduced vowels, and consonant clusters like 'lh' and 'nh' will be new. We'll train your ear with targeted exercises.",
  "onboarding.l1_intro_indic_gender": "Gender works differently",
  "onboarding.l1_intro_indic_gender_text": "Portuguese has masculine and feminine nouns like your language, but the assignments are different — 'leite' (milk) is masculine in Portuguese. We'll flag the surprising ones.",
  "onboarding.l1_intro_cyrillic_title": "A different alphabet",
  "onboarding.l1_intro_cyrillic_alphabet": "Latin instead of Cyrillic",
  "onboarding.l1_intro_cyrillic_alphabet_text": "Portuguese uses the Latin alphabet. Many letters look familiar but sound different — 'H' is silent, 'J' sounds like 'zh', and 'R' can trill or be guttural. We'll map each one.",
  "onboarding.l1_intro_cyrillic_sounds": "New sound patterns",
  "onboarding.l1_intro_cyrillic_sounds_text": "Portuguese has nasal vowels (ã, õ) and reduced unstressed vowels that don't exist in your language. The rhythm is also very different — stressed syllables are longer, unstressed ones almost disappear.",
  "onboarding.l1_intro_cyrillic_grammar": "Grammar similarities and differences",
  "onboarding.l1_intro_cyrillic_grammar_text": "Portuguese has no cases, which simplifies noun usage. But it adds articles (o/a) before nouns and has more verb tenses than you're used to, including the subjunctive.",

