  "onboarding.l1_intro_indic_sounds_text": "Certains sons portugais sont similaires aux vôtres, comme le 'r' rétroflex. Mais les voyelles nasales, les voyelles réduites et les groupes consonantiques comme 'lh' et 'nh' seront nouveaux. Nous entraînerons votre oreille avec des exercices ciblés.",
  "onboarding.l1_intro_indic_gender": "Le genre fonctionne différemment",
  "onboarding.l1_intro_indic_gender_text": "Le portugais a des noms masculins et féminins comme votre langue, mais les attributions sont différentes — 'leite' (lait) est masculin en portugais. Nous signalerons les surprenants.",
