  "onboarding.l1_intro_cyrillic_alphabet": "Latin au lieu du cyrillique",
  "onboarding.l1_intro_cyrillic_alphabet_text": "Le portugais utilise l'alphabet latin. Beaucoup de lettres semblent familières mais sonnent différemment — 'H' est muet, 'J' sonne comme 'jh' et 'R' peut rouler ou être guttural. Nous mapperons chacune.",
  "onboarding.l1_intro_cyrillic_sounds": "Nouveaux schémas sonores",
  "onboarding.l1_intro_cyrillic_sounds_text": "Le portugais a des voyelles nasales (ã, õ) et des voyelles atones réduites qui n'existent pas dans votre langue. Le rythme est aussi très différent — les syllabes toniques sont plus longues, les atones disparaissent presque.",
  "onboarding.l1_intro_cyrillic_grammar": "Similarités et différences grammaticales",
  "onboarding.l1_intro_cyrillic_grammar_text": "Le portugais n'a pas de cas, ce qui simplifie l'usage des noms. Mais il ajoute des articles (o/a) avant les noms et a plus de temps verbaux, dont le subjonctif.",

