  "onboarding.l1_intro_general_sounds": "অনন্য ধ্বনি",
  "onboarding.l1_intro_general_sounds_text": "ইউরোপীয় পর্তুগিজে নাসিক স্বরধ্বনি, হ্রাসিত ধ্বনি এবং একটি স্বতন্ত্র ছন্দ আছে।",
  "onboarding.l1_intro_general_grammar": "ব্যাকরণের মূল বিষয়",
  "onboarding.l1_intro_general_grammar_text": "পর্তুগিজে লিঙ্গযুক্ত বিশেষ্য, ক্রিয়া-বিভক্তি এবং পদাশ্রিত নির্দেশক আছে। আমরা প্রতিটি ধারণা ধীরে ধীরে পরিচয় করাব।",
  "onboarding.l1_intro_indic_title": "একটি নতুন লিপি",
  "onboarding.l1_intro_indic_alphabet": "ল্যাটিন বর্ণমালা",
  "onboarding.l1_intro_indic_alphabet_text": "পর্তুগিজ দেবনাগরী বা বাংলা লিপির পরিবর্তে ল্যাটিন বর্ণমালা (A-Z) ব্যবহার করে। আমরা প্রতিটি অক্ষর তার পর্তুগিজ ধ্বনি সহ পরিচয় করাব, যার মধ্যে ç, ã, õ, é, ê-এর মতো বিশেষ অক্ষর রয়েছে।",
  "onboarding.l1_intro_indic_sounds": "পরিচিত ও নতুন ধ্বনি",
  "onboarding.l1_intro_indic_sounds_text": "কিছু পর্তুগিজ ধ্বনি আপনার ভাষার মতো। কিন্তু নাসিক্য স্বরবর্ণ, হ্রস্ব স্বরবর্ণ এবং 'lh' ও 'nh'-এর মতো ব্যঞ্জনবর্ণ গুচ্ছ নতুন হবে। আমরা লক্ষ্যভিত্তিক অনুশীলনে আপনার কান প্রশিক্ষিত করব।",
  "onboarding.l1_intro_indic_gender": "লিঙ্গ ভিন্নভাবে কাজ করে",
  "onboarding.l1_intro_indic_gender_text": "পর্তুগিজে আপনার ভাষার মতো পুংলিঙ্গ ও স্ত্রীলিঙ্গ বিশেষ্য আছে, কিন্তু শ্রেণীবিন্যাস আলাদা — 'leite' (দুধ) পর্তুগিজে পুংলিঙ্গ। আমরা বিস্ময়কর গুলো চিহ্নিত করব।",
  "onboarding.l1_intro_cyrillic_title": "একটি ভিন্ন বর্ণমালা",
  "onboarding.l1_intro_cyrillic_alphabet": "সিরিলিকের বদলে ল্যাটিন",
  "onboarding.l1_intro_cyrillic_alphabet_text": "পর্তুগিজ ল্যাটিন বর্ণমালা ব্যবহার করে। অনেক অক্ষর পরিচিত দেখায় কিন্তু ভিন্নভাবে উচ্চারিত হয় — 'H' নীরব, 'J' 'ঝ'-এর মতো শোনায় এবং 'R' কম্পন বা কণ্ঠ্য হতে পারে।",
  "onboarding.l1_intro_cyrillic_sounds": "নতুন ধ্বনি নমুনা",
  "onboarding.l1_intro_cyrillic_sounds_text": "পর্তুগিজে নাসিক্য স্বরবর্ণ (ã, õ) এবং হ্রস্ব অনাঘাত স্বরবর্ণ আছে যা আপনার ভাষায় নেই। ছন্দও অনেক আলাদা — ঘাতযুক্ত দীর্ঘ, ঘাতহীন প্রায় অদৃশ্য।",
  "onboarding.l1_intro_cyrillic_grammar": "ব্যাকরণ মিল ও পার্থক্য",
  "onboarding.l1_intro_cyrillic_grammar_text": "পর্তুগিজে কারক নেই, যা বিশেষ্য ব্যবহার সরল করে। কিন্তু বিশেষ্যের আগে পদাশ্রিত নির্দেশক (o/a) যোগ করে এবং সম্ভাব্য সহ আরও বেশি ক্রিয়া কাল আছে।",

