  "onboarding.l1_intro_rtl_vowels": "Vogais escritas em todo o lado",
  "onboarding.l1_intro_rtl_vowels_text": "Ao contrário da tua língua, o português escreve todas as vogais explicitamente. Vais ver a, e, i, o, u em cada palavra. O português também tem vogais nasais (ã, õ) com sons próprios.",
