  "onboarding.l1_intro_general_sounds_text": "O português europeu tem vogais nasais, sons reduzidos e um ritmo distinto. Cada lição inclui guias de pronúncia adaptados a falantes da tua língua.",
  "onboarding.l1_intro_general_grammar": "Essenciais de gramática",
  "onboarding.l1_intro_general_grammar_text": "O português tem nomes com género, conjugações verbais e artigos. Vamos introduzir cada conceito gradualmente com comparações à tua língua onde útil.",
