  "onboarding.l1_intro_indic_alphabet": "O alfabeto latino",
  "onboarding.l1_intro_indic_alphabet_text": "O português usa o alfabeto latino (A-Z) em vez do devanágari ou bengali. Vamos apresentar cada letra com o seu som português, incluindo caracteres especiais como ç, ã, õ, é, ê.",
