  "onboarding.l1_intro_romance_advantage": "Close languages",
  "onboarding.l1_intro_romance_advantage_text": "Your language shares many words and structures with Portuguese. You'll progress faster than most learners.",
  "onboarding.l1_intro_romance_traps": "Watch out for false friends",
  "onboarding.l1_intro_romance_traps_text": "Some words look the same but mean different things. We'll highlight these throughout your journey so you avoid common mistakes.",
  "onboarding.l1_intro_romance_sounds": "New sounds to learn",
  "onboarding.l1_intro_romance_sounds_text": "European Portuguese has nasal vowels, reduced vowels, and unique sounds like 'lh' and 'nh' that don't exist in your language. We'll train your ear.",
